  "main.tf": "terraform {\n  required_version = \">= 1.6.0\"\n\n  required_providers {\n    aws = {\n      source  = \"hashicorp/aws\"\n      version = \"~> 6.60\"\n    }\n  }\n}\n\nprovider \"aws\" {\n  region = var.region\n}\n\ndata \"aws_availability_zones\" \"available\" {\n  state = \"available\"\n}\n\ndata \"aws_ami\" \"al2023\" {\n  most_recent = true\n  owners      = [\"amazon\"]\n\n  filter {\n    name   = \"name\"\n    values = [\"al2023-ami-2023.*-x86_64\"]\n  }\n}\n\nresource \"aws_vpc\" \"main\" {\n  cidr_block           = \"10.60.0.0/16\"\n  enable_dns_support   = true\n  enable_dns_hostnames = true\n}\n\nresource \"aws_subnet\" \"public\" {\n  vpc_id                  = aws_vpc.main.id\n  cidr_block              = \"10.60.1.0/24\"\n  availability_zone       = data.aws_availability_zones.available.names[0]\n  map_public_ip_on_launch = true\n}\n\nresource \"aws_internet_gateway\" \"main\" {\n  vpc_id = aws_vpc.main.id\n}\n\nresource \"aws_route_table\" \"public\" {\n  vpc_id = aws_vpc.main.id\n}\n\nresource \"aws_route\" \"public_default\" {\n  route_table_id         = aws_route_table.public.id\n  destination_cidr_block = \"0.0.0.0/0\"\n  gateway_id             = aws_internet_gateway.main.id\n}\n\nresource \"aws_route_table_association\" \"public\" {\n  subnet_id      = aws_subnet.public.id\n  route_table_id = aws_route_table.public.id\n}\n\nresource \"aws_security_group\" \"status\" {\n  name_prefix = \"status-page-\"\n  description = \"HTTP and HTTPS from anywhere, SSH from the admin range\"\n  vpc_id      = aws_vpc.main.id\n}\n\nresource \"aws_vpc_security_group_ingress_rule\" \"http\" {\n  security_group_id = aws_security_group.status.id\n  ip_protocol       = \"tcp\"\n  from_port         = 80\n  to_port           = 80\n  cidr_ipv4         = \"0.0.0.0/0\"\n}\n\nresource \"aws_vpc_security_group_ingress_rule\" \"https\" {\n  security_group_id = aws_security_group.status.id\n  ip_protocol       = \"tcp\"\n  from_port         = 443\n  to_port           = 443\n  cidr_ipv4         = \"0.0.0.0/0\"\n}\n\nresource \"aws_vpc_security_group_ingress_rule\" \"ssh_admin\" {\n  security_group_id = aws_security_group.status.id\n  ip_protocol       = \"tcp\"\n  from_port         = 22\n  to_port           = 22\n  cidr_ipv4         = var.admin_cidr\n}\n\nresource \"aws_vpc_security_group_egress_rule\" \"https_out\" {\n  security_group_id = aws_security_group.status.id\n  ip_protocol       = \"tcp\"\n  from_port         = 443\n  to_port           = 443\n  cidr_ipv4         = \"0.0.0.0/0\"\n}\n\nresource \"aws_instance\" \"status\" {\n  ami                    = data.aws_ami.al2023.id\n  instance_type          = \"t3.micro\"\n  subnet_id              = aws_subnet.public.id\n  vpc_security_group_ids = [aws_security_group.status.id]\n\n  metadata_options {\n    http_tokens = \"required\"\n  }\n\n  # The rules only allow traffic; nginx has to be installed and started.\n  user_data = <<-EOT\n    #!/bin/bash\n    dnf install -y nginx\n    systemctl enable --now nginx\n  EOT\n}\n",
